import{_ as o,o as t,c as a,a5 as r}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"寄生式继承","description":"寄生式（ parasitic ）继承是与原型式继承紧密相关。 就是寄生在一个已经拥有我们需要属性的对象上，再稍做修改得到我们所要的对象。 寄生式继承也是用来拓展原生构造函数原型上的方法。但又不会修改原生构造函数原型对象。 区别： 封装了一个函数，并在函数的内部以某种方式来增强对象。","frontmatter":{"title":"寄生式继承","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","对象、数组与函数"],"description":"寄生式（ parasitic ）继承是与原型式继承紧密相关。 就是寄生在一个已经拥有我们需要属性的对象上，再稍做修改得到我们所要的对象。 寄生式继承也是用来拓展原生构造函数原型上的方法。但又不会修改原生构造函数原型对象。 区别： 封装了一个函数，并在函数的内部以某种方式来增强对象。","sidebarWeight":150,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/面向对象程序设计/(80m)继承/(10m)寄生式继承.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/03-对象、数组与函数/(80m)继承/(10m)寄生式继承.md","filePath":"posts/JavaScript系统教程/03-对象、数组与函数/(80m)继承/(10m)寄生式继承.md"}'),n={name:"posts/JavaScript系统教程/03-对象、数组与函数/(80m)继承/(10m)寄生式继承.md"};function c(i,e,s,l,p,d){return t(),a("div",null,[...e[0]||(e[0]=[r('<div><h1 id="寄生式继承" tabindex="-1">寄生式继承 <a class="header-anchor" href="#寄生式继承" aria-label="Permalink to &quot;寄生式继承&quot;">​</a></h1><blockquote><p>本节目标：理解“寄生式继承”的核心思路，并能把它用于实际开发或面试表达。 寄生式（<code>parasitic</code>）继承是与原型式继承紧密相关。</p></blockquote><p>就是寄生在一个已经拥有我们需要属性的对象上，再稍做修改得到我们所要的对象。 寄生式继承也是用来拓展原生构造函数原型上的方法。但又不会修改原生构造函数原型对象。</p><p>**区别：**封装了一个函数，并在函数的内部以某种方式来增强对象，然后再像真的做了所有工作一样返回对象。如下： function createAnother(origin) { //通过调用构造函数创建了一个新对象 var clone = object(origin); //以某种方式来增强这个对象 clone.sayHi = function () { console.log(&#39;hi&#39;); }; //返回了这个对象 return clone; }</p><p><strong>使用：</strong> var person = { name: &#39;Nicholas&#39;, firends: [&#39;Shelby&#39;, &#39;Court&#39;, &#39;Van&#39;] }; var anotherPerson = createAnother(person); console.log(anotherPerson.sayHi);//&#39;hi&#39;</p><p>示例2 function createObject(o) { function F() {} F.prototype = o; return new F(); } function createChild(parent) { const child = createObject(parent); child.sayHi = function() { console.log(&#39;Hi from Child&#39;); }; return child; } const parent = { name: &#39;Parent&#39;, sayHello: function() { console.log(&#39;Hello from Parent&#39;); } }; const child = createChild(parent); console.log(child.name); // 输出: Parent child.sayHello(); // 输出: Hello from Parent child.sayHi(); // 输出: Hi from Child</p><p>在主要考虑对象而不是自定义类型和构造函数的情况下，寄生式继承是一种有用的模式。前面示范继承模式时使用的<code>object()</code>函数不是必需的；任何能够返回新对象的函数都适用于此模式。</p><p><strong>寄生式继承问题</strong> 寄生式继承如果为对象增加方法，会由于不能做到对象方法的复用而降低效率；</p></div>',1)])])}const m=o(n,[["render",c]]);export{h as __pageData,m as default};
